// window and object. Every lock sequence of one scope (LockCapCounters, LockScopeCounters) follows the same order.
func (q *Queries) LockReservedCounters(ctx context.Context, db DBTX, ids []uuid.UUID) error {
	_, err := db.Exec(ctx, lockReservedCounters, ids)
	return err
}

const lockReservedPolicies = `-- name: LockReservedPolicies :exec
SELECT p.category FROM operations.cap_policies p
WHERE EXISTS (SELECT 1 FROM operations.money_actions m WHERE m.operation_id = ANY ($1::uuid[]) AND m.state = 'reserved'
    AND m.category = p.category AND m.site_id IS NOT DISTINCT FROM p.site_id)
ORDER BY p.category, p.site_id NULLS FIRST
FOR SHARE OF p
`

// The policies of the reservations still held by operations @ids, which the caller holds, in the order every batch
// takes them: by category, the platform's first, then by site.
func (q *Queries) LockReservedPolicies(ctx context.Context, db DBTX, ids []uuid.UUID) error {
	_, err := db.Exec(ctx, lockReservedPolicies, ids)
	return err
}

const lockScopeCounters = `-- name: LockScopeCounters :exec
SELECT c.id FROM operations.cap_counters c
WHERE c.category = $1 AND c.site_id IS NOT DISTINCT FROM $2::uuid AND (
    (c.window_kind = 'day' AND c.window_start = $3) OR (c.window_kind = 'week' AND c.window_start = $4))
ORDER BY c.object_kind, c.window_kind, c.object_id
FOR UPDATE
`

type LockScopeCountersParams struct {
	Category  string
	SiteID    *uuid.UUID
	DayStart  time.Time
	WeekStart time.Time
}

// Every counter of a scope and category in a UTC day and ISO week, in the order every path locks its own
// three (LockCapCounters), the object's days by object after them.
func (q *Queries) LockScopeCounters(ctx context.Context, db DBTX, arg LockScopeCountersParams) error {
	_, err := db.Exec(ctx, lockScopeCounters,
		arg.Category,
		arg.SiteID,
		arg.DayStart,
		arg.WeekStart,
	)
	return err
}

const moneyActionOf = `-- name: MoneyActionOf :many
SELECT operation_id, category, site_id, object_kind, object_id, amount, currency, basis, policy_rev, day_start, week_start, expires_at, state, proof, confirmed_by, settled_at FROM operations.money_actions WHERE operation_id = $1
`

func (q *Queries) MoneyActionOf(ctx context.Context, db DBTX, operationID uuid.UUID) ([]OperationsMoneyAction, error) {
	rows, err := db.Query(ctx, moneyActionOf, operationID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []OperationsMoneyAction
	for rows.Next() {
		var i OperationsMoneyAction
		if err := rows.Scan(
			&i.OperationID,
			&i.Category,
			&i.SiteID,
			&i.ObjectKind,
			&i.ObjectID,
			&i.Amount,
			&i.Currency,
			&i.Basis,
			&i.PolicyRev,
			&i.DayStart,
			&i.WeekStart,
			&i.ExpiresAt,
			&i.State,
			&i.Proof,
			&i.ConfirmedBy,
			&i.SettledAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const moveCapCounters = `-- name: MoveCapCounters :exec
UPDATE operations.cap_counters SET reserved = reserved + $1, committed = committed + $2, count = count + $3
WHERE id = ANY ($4::bigint[])
`

type MoveCapCountersParams struct {
	Reserved  int64
	Committed int64
	Count     int32
	Ids       []int64
}

func (q *Queries) MoveCapCounters(ctx context.Context, db DBTX, arg MoveCapCountersParams) error {
	_, err := db.Exec(ctx, moveCapCounters,
		arg.Reserved,
		arg.Committed,
		arg.Count,
		arg.Ids,
	)
	return err
}

const setCapCounter = `-- name: SetCapCounter :exec
INSERT INTO operations.cap_counters (category, window_kind, window_start, object_kind, object_id, site_id, reserved,
    committed, count)
VALUES ($1, $2, $3, $4, $5, $6::uuid, $7,
    $8, $9)
ON CONFLICT (category, window_kind, window_start, object_kind, object_id, site_id)
DO UPDATE SET reserved = excluded.reserved, committed = excluded.committed, count = excluded.count
`

type SetCapCounterParams struct {
	Category    string
	WindowKind  string
	WindowStart time.Time
	ObjectKind  string
	ObjectID    string
	SiteID      *uuid.UUID
	Reserved    int64
	Committed   int64
	Count       int32
}

func (q *Queries) SetCapCounter(ctx context.Context, db DBTX, arg SetCapCounterParams) error {
	_, err := db.Exec(ctx, setCapCounter,
		arg.Category,
		arg.WindowKind,
		arg.WindowStart,
		arg.ObjectKind,
		arg.ObjectID,
		arg.SiteID,
		arg.Reserved,
		arg.Committed,
		arg.Count,
	)
	return err
}

const setCapPaused = `-- name: SetCapPaused :execrows
UPDATE operations.cap_policies SET paused_at = CASE WHEN $1::bool THEN now() END
WHERE category = $2 AND site_id IS NOT DISTINCT FROM $3::uuid AND (paused_at IS NULL) = $1::bool
`

type SetCapPausedParams struct {
	Paused   bool
	Category string
	SiteID   *uuid.UUID
}

// Pauses (@paused) or resumes a policy the caller holds FOR UPDATE; no row when it already is.
func (q *Queries) SetCapPaused(ctx context.Context, db DBTX, arg SetCapPausedParams) (int64, error) {
	result, err := db.Exec(ctx, setCapPaused, arg.Paused, arg.Category, arg.SiteID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const settleMoneyAction = `-- name: SettleMoneyAction :exec
UPDATE operations.money_actions SET state = $1, proof = $2, confirmed_by = $3, settled_at = now()
WHERE operation_id = $4
`

type SettleMoneyActionParams struct {
	State       string
	Proof       *string
	ConfirmedBy *uuid.UUID
	OperationID uuid.UUID
}

func (q *Queries) SettleMoneyAction(ctx context.Context, db DBTX, arg SettleMoneyActionParams) error {
	_, err := db.Exec(ctx, settleMoneyAction,
		arg.State,
		arg.Proof,
		arg.ConfirmedBy,
		arg.OperationID,
	)
	return err
}

const updateCapPolicy = `-- name: UpdateCapPolicy :one
UPDATE operations.cap_policies SET single_max = $1, daily_max = $2, weekly_max = $3,
    object_daily_max = $4, daily_count_max = $5, hard_single_max = $6,
    hard_daily_max = $7, hard_weekly_max = $8, rev = rev + 1, updated_at = now()
WHERE category = $9 AND site_id IS NOT DISTINCT FROM $10::uuid
RETURNING site_id, category, currency, single_max, daily_max, weekly_max, object_daily_max, daily_count_max, hard_single_max, hard_daily_max, hard_weekly_max, rev, updated_at, paused_at
`

type UpdateCapPolicyParams struct {
	SingleMax      int64
	DailyMax       int64
	WeeklyMax      int64
	ObjectDailyMax int64
	DailyCountMax  int32
	HardSingleMax  int64
	HardDailyMax   int64
	HardWeeklyMax  int64
	Category       string
	SiteID         *uuid.UUID
}

func (q *Queries) UpdateCapPolicy(ctx context.Context, db DBTX, arg UpdateCapPolicyParams) (OperationsCapPolicy, error) {
	row := db.QueryRow(ctx, updateCapPolicy,
		arg.SingleMax,
		arg.DailyMax,
		arg.WeeklyMax,
		arg.ObjectDailyMax,
		arg.DailyCountMax,
		arg.HardSingleMax,
		arg.HardDailyMax,
		arg.HardWeeklyMax,
		arg.Category,
		arg.SiteID,
	)
	var i OperationsCapPolicy
	err := row.Scan(
		&i.SiteID,
		&i.Category,
		&i.Currency,
		&i.SingleMax,
		&i.DailyMax,
		&i.WeeklyMax,
		&i.ObjectDailyMax,
		&i.DailyCountMax,
		&i.HardSingleMax,
		&i.HardDailyMax,
		&i.HardWeeklyMax,
		&i.Rev,
		&i.UpdatedAt,
		&i.PausedAt,
	)
	return i, err
}

const windowEnded = `-- name: WindowEnded :one
SELECT clock_timestamp() >= $1::timestamptz + interval '1 day' AS ended
`

// Whether the UTC day that starts at @day_start is over by the database's clock as it is now.
func (q *Queries) WindowEnded(ctx context.Context, db DBTX, dayStart time.Time) (bool, error) {
	row := db.QueryRow(ctx, windowEnded, dayStart)
	var ended bool
	err := row.Scan(&ended)
	return ended, err
}
